INSERT INTO dump_descriptions (base_key, description) VALUES ('creator', 'Adds an in-game actor-class manager with searchable lists for removing selected classes and adding them back, plus a configurable update delay.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
INSERT INTO dump_descriptions (base_key, description) VALUES ('temperaturenumber_logged', 'Adds numeric temperature readouts for dwarves and enemies, including boss-fight HUD indicators, with color changes for heat and freeze levels.') ON CONFLICT(base_key) DO UPDATE SET description=excluded.description, updated_at=CURRENT_TIMESTAMP;
